  for(const [key] of draftEditors){const host=root.querySelector('[data-draft-editor="'+key+'"]');if(!host)continue;const operations=rows.filter(t=>t.key===key&&t.part==='base'&&consentOperationKey(t.row.label));let box=host.querySelector('[data-operation-group]');if(!operations.length){box?.remove();continue;}if(!box){box=document.createElement('details');box.dataset.operationGroup='';box.className='su-operation-group';box.innerHTML='<summary></summary><p class="su-small">등록된 병원 안내는 빈 칸에만 적용하며, 이번 환자에 맞게 수정할 수 있습니다.</p><div class="su-actions"><button type="button" data-act="preview-operation-batch">병원 설정 확인·일괄 적용</button><button type="button" data-act="consent-operations">병원 운영 설정</button></div><div class="su-draft-inputs"></div>';host.append(box);}const missing=operations.filter(t=>!t.row.value.trim()||consentHasPlaceholder(t.row.value));box.querySelector('summary').textContent='병원 공통 안내 · '+(missing.length?'입력 '+missing.length+'개':'입력됨 · 확인/수정');if(box.dataset.initialized!=='true'){box.open=!!missing.length;box.dataset.initialized='true';}for(const t of operations){const label=host.querySelector('[data-draft-row="'+t.id+'"]');const target=box.querySelector('.su-draft-inputs');if(label&&label.parentElement!==target)target.append(label);}}
