  if(choice!=='apply'||!alive()||!form.isConnected)return;if(snapshot!==consentSnapshot()||revision!==sharedPrefs?.revision){error('작성 내용이나 병원 설정이 변경되었습니다. 다시 확인해주세요.');return;}
