 function consentKnownInfo(b,key,row){const operation=consentOperationReuse(row.label,consentPrefs().operations);if(operation&&!row.value.trim())return operation;const value=row.value.trim();if(b.kind==='other'&&key==='necessity'&&!value){if(row.label==='확인하거나 치료하려는 문제'&&b.diagnosis?.trim()&&!consentHasPlaceholder(b.diagnosis))return {label:'입력한 진단명 사용',value:b.diagnosis.trim()};if(row.label==='검사·처치명과 목적'&&b.title?.trim()&&!Object.values(titles).includes(b.title.trim()))return {label:'입력한 진료명 사용',value:b.title.trim()+' · 목적: [입력: 확인하려는 내용 또는 치료 목표]'};}if(b.kind==='surgery'&&key==='precautions'&&row.label==='이번 환자의 준비·관리·재진 계획'&&!value){const model=consentDraftModel(b,'precautions'),care=Array.isArray(model?.anesthesia)&&model.anesthesia.find(r=>r.token&&r.enabled&&r.value.trim()&&!consentHasPlaceholder(r.value));if(care)return {label:'입력한 마취 준비·관리 가져오기',value:care.value.trim()+'\n수술별 관리·재진: [입력: 상처·활동 관리, 재진 계획]'};}const phone=String(b.hospitalPhone||'').trim();if(b.kind==='surgery'&&key==='method'&&['수술명','이번 수술의 내용'].includes(row.label)&&!value&&b.title?.trim()&&!Object.values(titles).includes(b.title.trim()))return {label:'입력한 수술명 사용',value:b.title.trim()+(row.label==='이번 수술의 내용'?' · [입력: 부위·좌우와 예정 범위]':'')};if(b.kind==='admission'&&key==='precautions'&&row.label.includes('연락드릴 보호자')&&!value&&b.guardianName?.trim()&&b.guardianPhone?.trim())return {label:'보호자 연락처 사용',value:b.guardianName.trim()+' · '+b.guardianPhone.trim()};if(key!=='precautions'||!phone||value.includes(phone))return null;let placeholder='';if(row.label.includes('일정과 연락 방법'))placeholder='[입력: 다음 진료·검사 일정]';else if(b.kind==='admission'&&row.label==='면회와 병원 연락 방법')placeholder='[입력: 면회 안내]';else if(b.kind==='discharge'&&row.label==='병원 연락처와 진료시간 외 연락 방법')placeholder='진료시간 외 연락 방법: [입력: 연락 방법]';else return null;return {label:'병원 연락처 넣기',value:(value||placeholder)+' · 병원 전화: '+phone};}
 function reuseConsentInfo(button){const key=button.dataset.reuseInfo,index=Number(button.dataset.index),row=draftEditors.get(key)?.model?.base?.[index],info=row&&consentKnownInfo(readConsent(),key,row),input=root.querySelector('[data-draft-input="'+key+'"][data-part=base][data-index="'+index+'"]');if(!info||!input)return;input.value=info.value;changeDraftInput(input);input.focus({preventScroll:true});}
 async function changeDischargeMedication(select){const entry=draftEditors.get('method'),index=entry?.model?.base?.findIndex(r=>r.label==='약 이름·사용 방법·사용 기간'),row=entry?.model?.base?.[index];if(!row)return;const none=consentNoMedication(row.value),next=select.value,input=root.querySelector('[data-draft-input=method][data-part=base][data-index="'+index+'"]');if(next==='none'&&row.value.trim()&&!none){const choice=await consentDecision('퇴원약을 없음으로 바꿀까요?','입력한 퇴원약 내용과 복약 안내가 동의서에서 제외됩니다.',[['cancel','유지'],['none','퇴원약 없음',true]]);if(choice!=='none'||!select.isConnected){if(select.isConnected)select.value='yes';return;}}if(next==='none')input.value='없음';else if(none||next==='')input.value='';changeDraftInput(input);if(next==='yes'){select.value='yes';input.focus({preventScroll:true});}}
