 function refreshClinicalReview(){const host=root.querySelector('[data-clinical-review]');if(!host)return;const b=readConsent(),keys=consentReviewKeys(b),signature=JSON.stringify(keys.map(k=>[k,!!String(b[k]||'').trim(),consentHasPlaceholder(b[k])]));if(host.dataset.state===signature)return;host.dataset.state=signature;host.hidden=!keys.length;host.innerHTML='<h3>최종 검토할 설명</h3><p class="su-small">아래 ‘검토·서명으로’에서 전문을 확인합니다.</p><div class="su-actions">'+keys.map(key=>'<button type="button" data-review-field="'+key+'" data-consent-issue="'+key+'">'+esc(consentFieldLabel(key))+'</button>').join('')+'</div>';}
