 function proposeConsentReplacement(changes,{warnings=[],origin='설명'}={}){if(readConsent().kind==='surgery')changes=changes.map(c=>c.key==='method'?{...c,after:consentOptionalSurgeryRows(c.after).text}:c);clearConsentPending();const form=root.querySelector('[data-consent-form]'),notice=root.querySelector('[data-consent-auto-status]');if(blockConsentLength(changes))return;if(!changes.length){notice.textContent='적용할 새 내용이 없습니다.';return;}pendingReplacement={changes,context:explanationContext(readConsent()),warnings,origin,form};if(changes.some(c=>String(c.before).trim()&&!untouchedConsentPreset(readConsent(),c.key)&&!(c.key==='title'&&c.before===titles[readConsent().kind])&&!c.appendOnly)){const show=v=>typeof v==='boolean'?(v?'포함':'포함하지 않음'):v||'비어 있음';root.querySelector('[data-consent-replacement]').innerHTML='<h4>바꿀 항목 선택</h4><p>빈 항목과 수정하지 않은 기본 문구가 기본 선택됩니다. 직접 작성한 설명과 비용은 선택한 경우에만 바뀝니다.</p>'+changes.map((c,i)=>'<section class="su-replace-row"><label class="su-check"><input type="checkbox" data-replace-field="'+i+'"'+(c.before===''||untouchedConsentPreset(readConsent(),c.key)||c.key==='title'&&c.before===titles[readConsent().kind]?' checked':'')+'>'+esc(consentFieldLabel(c.key))+'</label><div class="su-grid"><div><small>현재 내용</small><p>'+esc(show(c.before))+'</p></div><div><small>새 내용</small><p>'+esc(show(c.after))+'</p></div></div></section>').join('')+'<div class="su-actions"><button type="button" data-act="apply-consent-replacement" class="su-primary">선택 항목 적용</button><button type="button" data-act="cancel-consent-replacement">취소</button></div>';notice.textContent=origin+' · 바꿀 항목을 선택해주세요.'+(warnings.length?' · '+warnings.join(' · '):'');return;}commitConsentReplacement(changes);}
 function showConsentRepeat(changes,{warnings=[],origin}){if(blockConsentLength(changes))return;const form=root.querySelector('[data-consent-form]'),notice=root.querySelector('[data-consent-auto-status]');pendingReplacement=null;root.querySelector('[data-consent-auto-choices]').replaceChildren();pendingRepeat={changes,warnings,origin,form,context:explanationContext(readConsent()),snapshot:consentSnapshot()};root.querySelector('[data-consent-replacement]').innerHTML='<p>이미 적용된 설명입니다. 작성한 환자별 내용은 유지됩니다.</p><div class="su-actions"><button type="button" data-act="consent-fill-missing">누락 항목만 채우기</button><button type="button" data-act="consent-reapply-all">전체 재적용</button><button type="button" data-act="cancel-consent-replacement">닫기</button></div>';notice.textContent='이미 적용됨 · 전체 재적용도 바꿀 항목을 비교한 뒤 선택합니다.';}
