 function repeatConsentSource(all){const p=pendingRepeat;if(!p||p.form!==root.querySelector('[data-consent-form]')||p.context!==explanationContext(readConsent())||p.snapshot!==consentSnapshot()){error('입력이 변경되었습니다. 설명을 다시 찾아주세요.');return;}const changes=all?p.changes:p.changes.filter(c=>!String(c.before).trim()||untouchedConsentPreset(readConsent(),c.key)||c.key==='title'&&c.before===titles[readConsent().kind]);pendingRepeat=null;root.querySelector('[data-consent-replacement]').replaceChildren();if(!changes.length){root.querySelector('[data-consent-auto-status]').textContent=all?'이미 같은 설명입니다. 환자별 내용을 확인해주세요.':'누락된 설명 항목이 없습니다. 작성 중인 환자별 입력은 유지됩니다.';return;}proposeConsentReplacement(changes,p);}
