 function commitConsentReplacement(changes){const p=pendingReplacement,f=root.querySelector('[data-consent-form]');if(!p||f!==p.form||p.context!==explanationContext(readConsent())){error('환자·진료가 변경되었습니다. 설명을 다시 찾아주세요.');return;}if(!changes.length){error('적용할 항목을 선택해주세요.');return;}if(changes.some(c=>consentValue(f.elements[c.key])!==c.before)){error('비교 중 직접 수정한 내용이 있습니다. 설명을 다시 불러와주세요.');return;}doc.body.explanationSources||={};autoApplied=changes.map(c=>({...c,previousSource:doc.body.explanationSources[c.key],previousReview:(doc.body.patientReviewFields||[]).includes(c.key)}));for(const c of changes)putConsentValue(f.elements[c.key],c.after);const context=explanationContext(readConsent());for(const c of changes){if(c.source)doc.body.explanationSources[c.key]={...c.source,text:c.after,context};else delete doc.body.explanationSources[c.key];if(c.needsReview||consentHasPlaceholder(c.after))doc.body.patientReviewFields=[...new Set([...(doc.body.patientReviewFields||[]),c.key].filter(k=>patientReviewKeys.includes(k)))];}root.querySelector('[data-consent-replacement]').replaceChildren();root.querySelector('[data-consent-auto-choices]').replaceChildren();root.querySelector('[data-act=undo-consent-auto]').hidden=false;root.querySelector('[data-consent-auto-status]').textContent=changes.length+'개 항목 적용 · '+p.origin+(p.warnings.length?' · '+p.warnings.join(' · '):'');pendingReplacement=null;syncConsentDirty();error('');}
 function refreshConsentExplanation(){const b=readConsent();for(const key of patientReviewKeys){const n=root.querySelector('[name="'+key+'"]');if(!n)continue;let info=n.parentElement.querySelector('[data-explanation-source]');const source=b.explanationSources?.[key];if(!source){info?.remove();continue;}if(!info){info=document.createElement('div');info.dataset.explanationSource=key;n.after(info);}info.className='su-explanation-source';info.textContent='출처 · '+source.title+(source.revision?' · v'+source.revision:'');}refreshDraftEditors();organizeConsentInputs();refreshPresetStatus();refreshClinicalReview();refreshAnesthesiaNotice();g.SurgeryConsentForm?.sync(root.querySelector('[data-consent-form]'),b);const linear=root.querySelector('.su-linear-form');if(linear){const review=linear.querySelector('[data-clinical-review]');if(review)review.hidden=true;}}

 function updateConsentReadiness(){const f=root.querySelector('[data-consent-form]');if(!f)return;refreshConsentExplanation();const b=readConsent(),missing=consentMissing(b),input=consentMissing(b,false),inputs=[...new Map(input.map(x=>[x.key,x])).values()],inputKeys=new Set(inputs.map(x=>x.key)),reviews=[...new Map(missing.filter(x=>!inputKeys.has(x.key)).map(x=>[x.key,x])).values()],n=root.querySelector('[data-consent-readiness]');const state=JSON.stringify([inputs,reviews]);if(n&&n.dataset.missing!==state){n.dataset.missing=state;const group=(name,items,kind)=>'<details data-readiness-group="'+kind+'"'+(items.length&&items.length<5?' open':'')+'><summary>'+name+' '+items.length+'개</summary><div>'+items.map(x=>'<button type="button" data-consent-issue="'+x.key+'">'+esc(x.label)+'</button>').join('')+'</div></details>';n.innerHTML=f.classList.contains('su-surgery-form')?(inputs.length?'<span>작성할 항목 '+inputs.length+'개</span><div>'+inputs.slice(0,1).map(x=>'<button type="button" data-consent-issue="'+x.key+'">'+esc(x.label)+'</button>'+(x.detail?'<p class="su-issue-detail">'+esc(x.detail)+'</p>':'')).join('')+'</div>':'<span>입력 완료 · 내용을 확인하고 서명을 받으세요.</span>'):(missing.length?group('작성할 항목',inputs,'input')+group('검토할 설명',reviews,'review'):'<span>필수 입력 완료 · 검토·서명으로 이동할 수 있습니다.</span>');}for(const name of ['doctor-fields','hospital',...(doc.body.patientId?['patient']:[])]){const el=root.querySelector('[data-consent-'+name+']');if(el&&missing.some(x=>el.querySelector('[name="'+x.key+'"]')))el.open=true;}scheduleConsentAreas();}

 function undoAutoConsent(){const f=root.querySelector('[data-consent-form]');let kept=0;for(const c of autoApplied){if(consentValue(f.elements[c.key])===c.after){putConsentValue(f.elements[c.key],c.before);if(c.previousSource)doc.body.explanationSources[c.key]=c.previousSource;else delete doc.body.explanationSources[c.key];doc.body.patientReviewFields=(doc.body.patientReviewFields||[]).filter(k=>k!==c.key);if(c.previousReview)doc.body.patientReviewFields.push(c.key);}else kept++;}autoApplied=[];syncConsentDirty();root.querySelector('[data-act=undo-consent-auto]').hidden=true;root.querySelector('[data-consent-auto-status]').textContent='최근 적용을 취소했습니다.'+(kept?' 직접 수정한 항목은 유지했습니다.':'');}
 function consentEducationContext(){const b=readConsent();return JSON.stringify([explanationContext(b),b.chartNumber||'',b.guardianName||'']);}
 function resetConsentEducation(message=''){educationSelection=null;educationBlocks=[];root.querySelector('[data-education-preview]')?.replaceChildren();const notice=root.querySelector('[data-education-notice]');if(notice)notice.textContent=message;}
