  refreshConsentTemplatePicker();refreshAnesthesiaPresetStatus();if(doctors){doctors.innerHTML=consentDoctors(body);doctors.querySelector('[data-consent-doctor-fields]').open=!!draft.doctorOpen;doctors.querySelector('[data-consent-tools]').open=!!draft.manageOpen;}
  if(JSON.stringify(previous?.templates)!==JSON.stringify(sharedPrefs?.templates))clearConsentPending();markConsentFields();limitConsentManagement();updateConsentReadiness();refreshDraftEditors();
