 async function reloadConsentTools(){await loadConsentPrefs();if(alive()&&prefsError)error(prefsError);}
 function limitConsentManagement(){for(const n of root.querySelectorAll('[data-consent-tools] input,[data-consent-tools] button,[data-consent-tools] select'))n.disabled=!sharedPrefs?.canManage||n.tagName==='SELECT'&&!sharedPrefs?.templateSpeciesEnabled;}
 async function importLocalConsentPrefs(){const local=localConsentPrefs(),p=consentPrefs();if(!sharedPrefs?.canManage)throw Error('병원 공통 서식 관리 권한이 필요합니다.');for(const x of local.doctors||[])if(!p.doctors.some(d=>d.license===x.license))p.doctors.push(x);for(const x of local.templates||[])if(!p.templates.some(t=>t.name===x.name))p.templates.push(x);await storeConsentPrefs(p);if(alive()){await reloadConsentTools();error('이 브라우저의 서식·수의사를 병원 공통 정보로 추가했습니다. 같은 이름의 서식은 기존 병원 자료를 유지했습니다.');}}
 function consentPrefKey(){return 'carestep-consent-tools:'+(a.preferencesIdentity?.()||a.identity());}
 function localConsentPrefs(){try{return JSON.parse(g.localStorage.getItem(consentPrefKey())||'{}');}catch{return {};}}
 function consentPrefs(){const local=localConsentPrefs();return {...structuredClone(sharedPrefs||{doctors:[],templates:[],revision:0,canManage:false}),lastDoctor:local.lastDoctor||''};}
 async function loadConsentPrefs(){const previous=sharedPrefs;try{const value=await request('consents/preferences');if(!alive())return;sharedPrefs=value;prefsError='';}catch(e){if(!alive())return;sharedPrefs=null;prefsError='병원 서식을 불러오지 못했습니다. 입력은 계속할 수 있습니다.';}if(alive())syncConsentPreferenceControls(previous);}
 function rememberConsentDoctor(value){try{g.localStorage.setItem(consentPrefKey(),JSON.stringify({...localConsentPrefs(),lastDoctor:value}));}catch{error('최근 수의사 선택을 이 브라우저에 기억하지 못했습니다.');}}
 async function storeConsentPrefs(p){if(!sharedPrefs)throw Error('병원 서식을 다시 불러온 뒤 저장해주세요.');if(!sharedPrefs.canManage)throw Error('병원 공통 서식 관리 권한이 필요합니다.');try{const r=await request('consents/preferences','POST',{revision:sharedPrefs.revision,doctors:p.doctors,templates:p.templates,...(sharedPrefs.operationsEnabled?{operations:p.operations||{}}:{})});if(alive()){sharedPrefs=r;rememberConsentDoctor(p.lastDoctor||'');}}catch(e){await loadConsentPrefs();throw e;}}
 // Use the existing hospital-scoped template store, permissions and revision checks.
 // These two templates contain common plans only; never copy a patient's answers into them.
