  reload.onclick=async()=>{saving=true;access();await loadConsentPrefs();saving=false;if(!alive()||!dialog.isConnected)return;if(!sharedPrefs){status.textContent='최신 설정 조회 실패 · 입력은 유지됩니다.';access();return;}const current=anesthesiaPreset(consentPrefs(),plan),box=dialog.querySelector('[data-anesthesia-compare]');box.replaceChildren();box.hidden=false;const title=document.createElement('b');title.textContent='현재 저장된 계획 · 아래 입력과 비교 후 저장';box.append(title);for(const key of ['method','precautions']){const p=document.createElement('p');p.textContent=(key==='method'?'마취 계획: ':'준비·관리: ')+(current?.body?.[key]||'미등록');box.append(p);}baseline=sharedPrefs.revision;save.textContent='비교한 입력으로 저장';status.textContent='입력은 유지했습니다. 현재 저장된 내용과 비교한 뒤 저장하세요.';access();};
  save.onclick=async()=>{if(saving||!sharedPrefs?.canManage)return;if(baseline!==sharedPrefs.revision){status.textContent='병원 설정이 변경되었습니다. 최신 설정을 확인해주세요.';access();return;}
   const values=Object.fromEntries(['method','precautions'].map(key=>[key,dialog.querySelector('[data-anesthesia-setting='+key+']').value.trim()]));if(!values.method){status.textContent='기본 마취 계획을 입력해주세요.';return;}if(Object.values(values).some(v=>v.length>2000||consentHasPlaceholder(v))){status.textContent='각 계획은 2,000자 이내로 작성하고 미완성 입력 표시를 정리해주세요.';return;}
   const p=consentPrefs(),name=anesthesiaPresetNames[plan],i=p.templates.findIndex(t=>t.name===name);if(i>=0&&!isAnesthesiaPreset(p.templates[i])){status.textContent='같은 이름의 일반 서식이 있습니다. 일반 서식 이름을 먼저 변경해주세요.';return;}if(i<0&&p.templates.length>=50){status.textContent='병원 서식은 최대 50개까지 등록할 수 있습니다. 사용하지 않는 서식을 정리해주세요.';return;}
   const template={name,species:'both',body:{kind:'surgery',title:name,generalAnesthesia:plan==='general',diagnosis:'',necessity:'',method:values.method,risks:'',precautions:values.precautions,cost:''}};if(i>=0)p.templates[i]=template;else p.templates.push(template);
   saving=true;access();status.textContent='저장 중…';try{await storeConsentPrefs(p);if(!alive())return;dialog.close();refreshConsentTemplatePicker();refreshAnesthesiaPresetStatus();error('병원 기본 계획을 저장했습니다. 작성 중인 동의서는 유지됩니다.');}catch(e){if(dialog.isConnected)status.textContent=e.message+' 입력은 유지됩니다. 최신 설정을 확인한 뒤 다시 저장해주세요.';}finally{saving=false;if(dialog.isConnected)access();}
  };dialog.showModal();
