 async function loadAnesthesiaPreset(){
  const form=root.querySelector('[data-consent-form]'),snapshot=consentSnapshot(),plan=anesthesiaPlan(readConsent());if(!['general','sedation'].includes(plan)){error('마취 계획을 먼저 선택해주세요.');return;}
  await loadConsentPrefs();if(!alive()||!form.isConnected)return;if(!sharedPrefs){error('병원 설정을 불러오지 못했습니다. 입력은 유지됩니다. 다시 시도해주세요.');return;}if(snapshot!==consentSnapshot()){error('작성 내용이 변경되었습니다. 다시 불러와주세요.');return;}
  const template=anesthesiaPreset(consentPrefs(),plan);if(!template){error('저장된 기본 계획이 없습니다. 기본 계획 저장·관리에서 등록해주세요.');return;}
  const b=readConsent(),models=[];for(const key of ['method','precautions']){const model=consentDraftModel(b,key),rows=model?.anesthesia,value=template.body[key]?.trim();if(!Array.isArray(rows)||!value)continue;const target=rows.find(r=>r.token&&r.enabled&&!r.optional);if(!target||target.value.trim())continue;target.value=value;const after=consentDraftText(model);if(after.length>consentLimit(key)){error('기본 계획을 넣으면 설명 길이 한도를 넘습니다. 입력은 유지됩니다.');return;}models.push({key,after,value});}
  if(!models.length){error('적용할 빈 마취 입력칸이 없습니다. 작성한 내용은 유지됩니다.');return;}
  const revision=sharedPrefs.revision,choice=await consentDecision('병원 기본 계획을 불러올까요?',models.map(x=>(x.key==='method'?'마취 계획':'준비·회복 관리')+'\n'+x.value).join('\n\n')+'\n\n빈칸에만 적용합니다. 이번 환자의 실제 계획에 맞게 수정·확인해주세요.',[['cancel','취소'],['apply','확인한 계획 불러오기']]);
  if(choice!=='apply'||!alive()||!form.isConnected)return;if(snapshot!==consentSnapshot()||revision!==sharedPrefs?.revision){error('작성 내용이나 병원 설정이 변경되었습니다. 다시 불러와주세요.');return;}
  for(const x of models)form.elements[x.key].value=x.after;doc.body.patientReviewFields=[...new Set([...(doc.body.patientReviewFields||[]),...models.map(x=>x.key)])];syncConsentDirty();error('기본 계획을 불러왔습니다. 환자별 위험·검사 결과와 비용은 유지됩니다.');
 }
 const consentTemplateKeys=['kind','title','generalAnesthesia','diagnosis','necessity','method','risks','precautions','cost'];
 function consentTemplatePicker(b){const p=consentPrefs(),items=p.templates.map((t,i)=>({t,i})).filter(x=>!isAnesthesiaPreset(x.t)&&x.t.body.kind===b.kind&&consentTemplateMatches(x.t,b.species)).sort((a,c)=>consentTemplateRank(a.t,b.species)-consentTemplateRank(c.t,b.species));return '<label>'+(b.kind==='transfusion'?'병원 수혈 계획 서식':'자주 쓰는 병원 서식')+'<select data-consent-template><option value="">'+(items.length?'서식 선택':'이 종류에 등록된 서식 없음')+'</option>'+items.map(({t,i})=>'<option value="'+i+'">'+esc(t.name)+' · '+esc(consentTemplateSpeciesLabel(t))+'</option>').join('')+'</select></label>'+(b.kind==='transfusion'?'<p class="su-small">병원에 저장한 검사·관찰 계획을 불러온 뒤 이번 환자의 검사 결과와 시행 계획을 확인하세요.</p>':'');}
 function refreshConsentTemplatePicker(){const n=root.querySelector('[data-consent-template-picker]');if(n)n.innerHTML=consentTemplatePicker(readConsent());}
 function consentTemplateSpeciesSelect(value,attr){return '<select '+attr+' aria-label="서식 동물종"'+(!sharedPrefs?.templateSpeciesEnabled?' disabled':'')+'>'+[['unknown','미지정 · 사용 시 확인'],['dog','강아지'],['cat','고양이'],['both','강아지·고양이 공통']].map(([v,label])=>'<option value="'+v+'"'+(v===(value||'unknown')?' selected':'')+'>'+label+'</option>').join('')+'</select>';}
 function consentTools(b){const p=consentPrefs();return (prefsError?'<p class="su-warning">'+esc(prefsError)+'</p>':'')+((localConsentPrefs().templates?.length||localConsentPrefs().doctors?.length)?'<p class="su-small">이 브라우저에만 저장된 자료가 있습니다. 설명에 환자 정보가 없는지 확인한 뒤 공유하세요.</p><button type="button" data-act="import-consent-prefs">이 브라우저 자료를 병원에 공유</button>':'')+'<button type="button" data-act="consent-operations">병원 운영 설정</button><button type="button" data-act="reload-consent-prefs">병원 서식 새로고침</button><details data-consent-tools><summary>서식 저장·관리</summary><p class="su-small">병원 공통 서식으로 저장되어 다른 진료실 PC에서도 사용할 수 있습니다. 환자·보호자 정보와 서명·동의 확인은 포함하지 않습니다. 설명 문구에도 개인 정보를 넣지 마세요.</p><div class="su-actions su-template-row"><input data-consent-template-name aria-label="서식 이름" placeholder="예: 복부 초음파" maxlength="100">'+consentTemplateSpeciesSelect('unknown','data-consent-template-species')+'<button type="button" data-act="save-consent-template">현재 설명을 서식으로 저장</button></div>'+p.templates.map((t,i)=>isAnesthesiaPreset(t)?'':'<div class="su-actions su-template-row"><input data-consent-template-rename="'+i+'" aria-label="서식 이름 수정" value="'+esc(t.name)+'" maxlength="100">'+consentTemplateSpeciesSelect(t.species,'data-template-species-edit="'+i+'"')+'<button type="button" data-rename-consent-template="'+i+'">수정 저장</button><button type="button" data-delete-consent-template="'+i+'">삭제</button></div>').join('')+'</details>';}
