 function consentMissing(b,includeReview=true){const names={...consentRequired,...Object.fromEntries(sectionFields(b).map(([k,l])=>[k,l]))},missing=Object.entries(names).filter(([k])=>!String(b[k]||'').trim()).map(([key,label])=>({key,label}));for(const [key,x] of Object.entries(b.explanationSources||{}))if(includeReview&&x.context!==explanationContext(b))missing.push({key,label:names[key]+' · 변경 후 재확인'});if(String(b.diagnosis||'').includes('[환자별 진단 확인 필요]'))missing.push({key:'diagnosis',label:'자료의 질환명을 환자 진단·의심 소견으로 확인'});for(const key of patientReviewKeys)if(consentHasPlaceholder(b[key])&&!missing.some(x=>x.key===key))missing.push({key,label:names[key]+' · 기본 문구의 입력란 작성'});for(const key of includeReview?b.patientReviewFields||[]:[])if(!missing.some(x=>x.key===key))missing.push({key,label:names[key]+(isConsentPresetSource(b.explanationSources?.[key])?' · 환자별 내용 확인':' · 환자·진료 변경 후 재확인')});if(!specialConsent(b)&&anesthesiaPlan(b)==='review')missing.push({key:'generalAnesthesia',label:'마취·진정 계획과 설명 일치 확인'});missing.push(...consentLengthIssues(b));const timeIssue=consentTimeIssue(b);if(timeIssue)missing.push(timeIssue);if(b.emergency&&!String(b.emergencyReason||'').trim())missing.push({key:'emergencyReason',label:'사후 설명 사유'});return missing;}
