  if(act==='preview-operation-batch'){run(previewOperationBatch);return;}if(button.dataset.loaderTab){selectConsentLoader(button.dataset.loaderTab);return;}if(act==='confirm-clinical-review'||act==='confirm-final-review'){if(button.type!=='submit')run(confirmClinicalReview);return;}if(button.dataset.reuseInfo){reuseConsentInfo(button);return;}if(act==='view-consent-preset'){const n=root.querySelector('[data-draft-preview]:not([hidden])')||root.querySelector('[name=necessity]');n?.scrollIntoView({block:'center',behavior:'smooth'});if(n){n.setAttribute('tabindex','-1');n.focus({preventScroll:true});}return;}if(button.dataset.expandConsent){const n=root.querySelector('[name="'+button.dataset.expandConsent+'"]');n.dataset.expanded=String(n.dataset.expanded!=='true');resizeConsentAreas();return;}
