  if(button.dataset.consentIssue){const key=button.dataset.consentIssue;if(!root.querySelector('[name="'+key+'"],[data-sign="'+key+'"]')&&doc?.status==='draft'&&canEdit()){if(dirty&&!g.confirm('내용을 수정하면 입력한 서명이 지워집니다. 수정할까요?'))return;dirty=false;editConsent();}focusConsentField(key);return;}
